        resource_url: "https://api.discogs.com/artists/18839",
        thumbnail_url:
          "https://i.discogs.com/hDRTa2gbOic6JYKtjzTydCIKPaXHYqNzSnMpLZzNPgc/rs:fit/g:sm/q:90/h:393/w:300/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9BLTE4ODM5/LTE1MDk0MTkyNjAt/MjU0MC5qcGVn.jpeg",
