    title: "Untitled ",
    notes:
      "The fourth Led Zeppelin album released on November 8, 1971, intentionally left untitled, with no indication it was by Led Zeppelin on original release - although many have commonly referred to it as \"Led Zeppelin IV\", \"Zoso\", \"Symbols\" or other unofficial titles. On Discogs, the title of this release is \"Untitled\", unless specifically titled otherwise, i.e. \"Led Zeppelin\" or \"IV\" (as some later versions).\r\n\r\nIn the UK, there are at least eight known vinyl red/plum 7-digit Deluxe cat# versions. To help simplify Release Notes, it may be easier to add the Version Number as below (Plus any potential variants to that numbered Version):\r\n1. Label: [url=http://www.discogs.com/viewimages?release=2893139]Version 1[/url]\r\nOriginal issue, Grant credit & inverted feather logo on B-side \r\n2. Label: [url=http://www.discogs.com/viewimages?release=5135884]Version 2[/url]\r\nAs Version 1, but with feather logo corrected on B-side.\r\n3. Label: [url=http://www.discogs.com/viewimages?release=7535664]Version 3[/url]\r\nAs Version 1 misprinted inverted feather logo on B-side, but with two label over-stickers.\r\n4. Label: [url=http://www.discogs.com/Led-Zeppelin-Untitled/release/7028785]Version 4[/url]\r\nGrant credit erased by 2 label over-stickers to Version 2. One adding band name at top, the other adding publishers/producer at bottom.\r\n5. Label: [url=http://www.discogs.com/viewimages?release=439898]Version 5[/url]\r\nStickers replaced by printed credits for the Version 3 data. However, B-side has title wrongly as 'Misty Mountain Top'. \"Under licence...\" text also added below Atlantic logo.\r\n6. Label: [url=http://www.discogs.com/viewimages?release=4598377]Version 6[/url]\r\nAs Version 5, but Yet the feather logo is again inverted on B-side.\r\n7. Label: [url=http://www.discogs.com/release/5547932]Version 7[/url]\r\nB-side track corrected to 'Misty Mountain Hop' and yet the feather logo is again inverted on B-side.\r\n8.  Label: [url=http://www.discogs.com/viewimages?release=3075403]Version 8[/url]\r\nAs Version 5, but B-side track corrected to 'Misty Mountain Hop' and the feather logo on B-side corrected and is the right way up. \r\nFurthermore: A 'Grant' text credit may still be extant on the grey liner of the Version 3 issues and onward.\r\n(Kinney 'K' cat# prefixes then followed, on Atlantic orange/green labels)\r\n\r\nAccording to [url=https://edition.cnn.com/2023/11/09/style/led-zeppelin-album-cover-mystery-solved-intl-scli-gbr/index.html]CNN[/url] the 'Stick Man' is a colored copy of a black and white photograph called 'A Wiltshire Thatcher', taken by Ernest Howard Farmer in the 1890s.  The thatcher in question is a man named [url=https://deadline.com/2023/11/led-zeppelin-iv-cover-photo-1235596856/]Lot Long,[/url] who was 69 years old at the time Farmer took the photo.",
    data_quality: "Correct",
