    title: "Who's Next",
    notes:
      'Fifth studio album by The Who, recorded April–June 1971, at [l=Stargroves] and [l=Olympic Studios], Barnes, and associate-produced by [a=Glyn Johns]. \r\n\r\nReleased July/August 1971, and reached #1 in the U.K. charts, the only time an album by The Who topped the charts in any country. Reissued in 1995 as an expanded edition with bonus tracks, and again in 2003 as a deluxe edition.\r\n\r\nThe album was developed from an abandoned rock opera project called Lifehouse, conceived by [a=Pete Townshend].\r\n\r\nThe front cover image was taken by photographer [url=/artist/2211209]Ethan A. Russell[/url] on the way to a gig in Leicester, depicting the band having "urinated" on a concrete monolith in a slag heap, in a scene inspired by Stanley Kubrick\'s film 2001: A Space Odyssey.\r\n\r\nSome versions exist omitting the track "Won\'t Get Fooled Again," and with different cover art and title (e.g., "Going Mobile," "Baba O\'Riley," etc.).',
