    title: '"Heroes"',
    notes:
      "12th studio album released October 1977.\r\n\r\nBetween [m=22382] and [m=22318] it forms the middle part of Bowie's so-called \"Berlin Trilogy\", which was created in collaboration with [a634]. In “Heroes” Low's sound was developed in a positive direction. Heroes” is the only one of the three albums that was recorded entirely in Berlin. It was produced by Bowie and [a55761], with recording engineer [a60619].\r\n\r\nPrior to the release of the album an edited version of the title track was released in three languages on singles - English, French and German.  \r\n\r\nThe original French & German RCA albums contained the title track with the vocals from these edits in combined dual language versions - English/French & English/German respectively.\r\n\r\nSingles from this release:\r\n[m=49841]\r\n[m=97315]",
