    title: "Discovery",
    notes:
      "Samples contained on the album:\r\n'One More Time: \"More Spell On You\" performed by [a=Eddie Johns] (uncredited). \r\n'Aerodynamic': \"Il Macquillage Lady\" performed by [a=Sister Sledge] (uncredited). \r\n'Digital Love': \"I Love You More\" performed by [a=George Duke]. \r\n'Harder, Better, Faster, Stronger': \"Cola Bottle Baby\" performed by [a=Edwin Birdsong].\r\n'Crescendolls': \"Can You Imagine\" performed by [a=The Imperials].\r\n'Superheroes': \"Who's Been Sleeping In My Bed\" performed by [a=Barry Manilow].\r\n'High Life': \"Break Down For Love\" performed by [a=Tavares] (uncredited). \r\n'Face To Face': \"Evil Woman\" performed by [a=Electric Light Orchestra] (uncredited).\r\n'Too Long': \"First Come, First Serve\" (rhythm)  performed by [a=Rose Royce] (uncredited).\r\nThe uncredited samples on 'Discovery' were found one by one and technically reproduced by Daft Punk fans all over the world.\r\n\r\nSingles taken from this release: \r\n1. [m=26637]\r\n2. [m=26797]\r\n3. [m=26808]\r\n4. [m=26687]\r\n5. [m=27027]\r\n\r\nConcepts:\r\nThe Daft Club\r\nAll the copies of 'Discovery' were released with a 'Daft Club' card included that permitted a web access to the Daft Club (Daftpunk.com). An exclusive unreleased track ('Ouverture') and several remixes (streaming only) were then accessible.\r\nAfter several technical problems (one of them omitted Mac users to connect to the site and asked them to search on peer to peer networks, such as Napster, to download 'Ouverture' - which came in total contradiction with the existence of the club), the concept was abandoned.\r\n\r\n'Interstella 5555: The 5tory Of The 5ecret 5tar 5ystem'\r\nClick [url=http://www.discogs.com/Daft-Punk-Interstella-5555-The-5tory-Of-The-5ecret-5tar-5ystem/master/26948]here[/url] to access the master page of the movie related to 'Discovery'.",
