    title: "Deep Purple In Rock",
    notes:
      'The first studio album to feature a new line-up:\r\n[a309402] • Guitar / [a349634] • Vocals / [a262410] • Organ / [a261635] • Drums / [a123906] • Bass\r\n\r\nSingles released: Track 1 - [m=536204] / Track 3 - [m=277281] / [m10628]\r\n\r\nDeep Purple In Rock is the fourth studio album by British rock band [a170355], recorded from October 1969 to April 1970 at the [url=https://www.discogs.com/label/264182-IBC-Studios]IBC Studio[/url], [url=https://www.discogs.com/label/268136-De-Lane-Lea-Studios]De Lane Lea Studios[/url] and [url=https://www.discogs.com/label/217694-Abbey-Road-Studios]Abbey Road Studios[/url], all in London.\r\nFirst issued in UK, June 5, 1970 on Harvest SHVL 777:\r\nThe original album came in an outside laminated gatefold sleeve. The inner gatefold had lyrics on the left and five black & white photos of the individual band members & credits on the right.\r\nThe main identifiers of the earliest UK copies: \r\n- The upper rim text on labels begins with \'THE GRAMOPHONE CO LTD\';\r\n- No EMI logo on labels;\r\n- Small Ⓟ icon (left of 1970 on labels);\r\n- Only one bold line around the EMI/Harvest logo on the front sleeve;\r\n- Plain factory inner sleeve with \'Patent Nos. 1125555\' text on the left and \'Made In Great Britain\' text on the right at the bottom of the sleeve.\r\n\r\nIn Mexico the album also included "Black Night", a single recorded soon after the main album sessions.\r\nThe U.S. and Japanese releases of the album cut the intro to "Speed King" lasting just over a minute.\r\nSee also [url=https://en.wikipedia.org/wiki/Deep_Purple_in_Rock]Wikipedia[/url]\r\n\r\nThe main title could be spelled as "Deep Purple In Rock" according to the logo of the 1st UK Harvest Edition [r=1849291], or, as many editions are referred to as, "In Rock".',
