    title: "Synchronicity",
    notes:
      "The English rock band [a7987] has released five studio albums between 1978 and 1983.\r\n\r\nFifth and final studio album released 1983.\r\n\r\nThe album's original cover artwork, designed by Norman Moore, was available in 36 variations, with different arrangements of the colour stripes and showing different photographs of the band members, taken by [a=Duane Michals]. The most common version Sting is reading a copy of Jung's \"Synchronicity\". In the USA and Canada a good majority of the pressings were issued on audiophile vinyl which appears black like most records, but is actually purple or brown when held up to the light.\r\n\r\n[url=https://www.discogs.com/forum/thread/393120]This Discogs Forum thread[/url] discusses the U.S. sleeve variations.\r\n\r\nFirst UK release of CD with catalog number CDA 63735 was 18 Nov 1983.",
